import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
const require = createRequire(import.meta.url);
const root = dirname(require.resolve('leaflet/package.json'));
const css = readFileSync(join(root, 'dist/leaflet.css'), 'utf8').replace(/url\(images\/([^)]*)\)/g, (_, name) =>
  `url(data:image/png;base64,${readFileSync(join(root, 'dist/images', name)).toString('base64')})`);
const js = readFileSync(join(root, 'dist/leaflet.js'), 'utf8').replace(/\/\/# sourceMappingURL=.*$/gm, '');
mkdirSync(new URL('../src/generated/', import.meta.url), { recursive: true });
writeFileSync(new URL('../src/generated/leaflet-assets.ts', import.meta.url),
  '// Generated by scripts/build-map-assets.mjs. License: assets/leaflet-LICENSE.txt\n' +
  `export const leafletCss = ${JSON.stringify(css)};\nexport const leafletJs = ${JSON.stringify(js)};\n`);
writeFileSync(new URL('../assets/leaflet-LICENSE.txt', import.meta.url), readFileSync(join(root, 'LICENSE')));
